//! Real ordinary-argv generation over the existing resident pipeline; no oracle claim.
#[path="../../../shared/test_scratch.rs"]mod scratch;
#[path="../../../shared/test_native_transport.rs"]mod native_transport;
use std::{fs,path::Path,process::Output,ffi::OsStr,time::Duration};
#[global_allocator]static ALLOC:mimalloc::MiMalloc=mimalloc::MiMalloc;
fn invoke(transport:&native_transport::LibraryTransport<'_>,root:&Path,cache:&Path,names:&[&str])->Output{
 let mut args=vec![OsStr::new("generate-ordinary"),OsStr::new("--workspace"),root.as_os_str(),OsStr::new("--cache-root"),cache.as_os_str(),OsStr::new("--check")];args.extend(names.iter().map(|name|OsStr::new(name)));
 transport.run_program(Path::new(env!("CARGO_BIN_EXE_dmbc")),&args,Duration::from_secs(60)).unwrap()
}
#[test]#[ignore="actual resident CLI; run only in the owned bounded integration slot"]
fn actual_ordinary_native_generation_check_uses_real_request_and_sealed_text_without_source_writes(){
 let outer=scratch::dir("ordinary-native-gen-cli");let root=outer.join("source");let cache=outer.join("cache");fs::create_dir_all(root.join("code/engine/_generated")).unwrap();fs::create_dir_all(root.join("tools/ci")).unwrap();fs::create_dir(&cache).unwrap();
 let source=b"/obj/box\n    var/count\n    proc/probe()\n        return count\n";let manifest=b"#include \"code/probe.dm\"\n";fs::write(root.join("code/probe.dm"),source).unwrap();fs::write(root.join("deepquarry.dme"),manifest).unwrap();fs::write(root.join("tools/ci/lint_scopes.toml"),b"").unwrap();
 let transport_root=outer.join("transport");fs::create_dir(&transport_root).unwrap();let transport=native_transport::LibraryTransport{root:&transport_root,namespace:format!("ordinary-generation-{}",std::process::id())};
 for _ in 0..2{let output=invoke(&transport,&root,&cache,&["deps"]);assert_eq!(output.status.code(),Some(1),"{}",String::from_utf8_lossy(&output.stderr));let end=output.stdout.iter().position(|b|*b==b'\n').expect("sealed ordinary header");let header:serde_json::Value=serde_json::from_slice(&output.stdout[..end]).unwrap();let text=&output.stdout[end+1..];assert_eq!(header["schema"],"native-ordinary-generation-v1");assert_eq!(header["status"],"completed");assert_eq!(header["clean"],false);assert_eq!(header["committed"],false);assert_eq!(header["length"].as_u64(),Some(text.len()as u64));assert_eq!(header["hash"],serde_json::to_value(dq_analyze::selected_exclusions_wire::Hex128(xxhash_rust::xxh3::xxh3_128(text))).unwrap());assert!(String::from_utf8_lossy(text).contains("[gen/deps] stale -- run `analyze gen deps`"));assert_eq!(fs::read(root.join("code/probe.dm")).unwrap(),source);assert_eq!(fs::read(root.join("deepquarry.dme")).unwrap(),manifest);assert!(!root.join("code/engine/_generated/deps.dm").exists());}
 let bad=invoke(&transport,&root,&cache,&["unknown"]);assert_eq!(bad.status.code(),Some(2));assert!(bad.stdout.is_empty());assert!(!root.join("code/engine/_generated/deps.dm").exists());
}

fn ui_json_request(root:&Path,cache:&Path)->std::path::PathBuf{
 let dmbc::request::Command::Build(build)=dmbc::cli::parse(&["prepare-query".into(),root.join("deepquarry.dme").to_string_lossy().into_owned()]).unwrap()else{panic!("real request parser")};let mut build=*build;build.engine_template=None;build.bootstrap_catalog=false;build.progress_enabled=false;build.no_cache=true;build.exact_inputs=true;build.workers=1;build.timeout_seconds=Some(60);build.cache_root=Some(cache.to_owned());build.policy_inputs=Some(dmbc::policy_request::PolicyInputRequest{analysis_context:Some(dmbc::policy_request::AnalysisContext::OriginalAnalyze0290),workspace:Some(dmbc::policy_request::WorkspacePolicyRequest{root:root.to_owned(),recursive_roots:vec![root.join("code")],configuration:root.join("tools/ci/lint_scopes.toml")}),workspace_generators:vec![dmbc::GeneratorName::UiTypes],..Default::default()});let path=cache.join("actual-ui-check.json");fs::write(&path,serde_json::to_vec(&serde_json::json!({"build":build,"check":true})).unwrap()).unwrap();path
}
#[test]#[ignore="actual resident generation IPC; run exact in the bounded owned integration slot"]
fn actual_ui_zero_output_diagnostic_and_mixed_files_complete_json_and_ordinary_report_without_fake_output(){
 let outer=scratch::dir("ordinary-native-ui-diagnostic-only");let root=outer.join("source");let cache=outer.join("cache");let transport_root=outer.join("transport");fs::create_dir_all(root.join("code")).unwrap();fs::create_dir_all(root.join("tools/ci")).unwrap();fs::create_dir(&cache).unwrap();fs::create_dir(&transport_root).unwrap();fs::write(root.join("deepquarry.dme"),"#include \"code/probe.dm\"\n").unwrap();fs::write(root.join("tools/ci/lint_scopes.toml"),"").unwrap();let root=fs::canonicalize(root).unwrap();let cache=fs::canonicalize(cache).unwrap();let transport=native_transport::LibraryTransport{root:&transport_root,namespace:format!("ui-no-output-{}",std::process::id())};
 let define=include_str!("../../../../../code/defines/engine/declare/markers.dm").lines().find(|line|line.starts_with("#define CAPABILITIES(T)")).unwrap();let empty="/datum/ui_empty\nCAPABILITIES(/datum/ui_empty)\n    interface(\"Empty\")\n";
 for case in 0..3{let entries=match case{0=>empty.to_owned(),1=>format!("{empty}/datum/ui_z\nCAPABILITIES(/datum/ui_z)\n    interface(\"Zed\")\n    ui_shape(count = num())\n/datum/ui_a\nCAPABILITIES(/datum/ui_a)\n    interface(\"Alpha\")\n    ui_shape(count = num())\n"),_=>"/datum/ui_empty\n".to_owned()};let source=format!("{define}\n{entries}");fs::write(root.join("code/probe.dm"),&source).unwrap();let control=ui_json_request(&root,&cache);let args=[OsStr::new("generate"),control.as_os_str(),OsStr::new("--jsonl")];let output=transport.run_program(Path::new(env!("CARGO_BIN_EXE_dmbc")),&args,Duration::from_secs(30)).unwrap();
  if case==2{assert_eq!(output.status.code(),Some(2),"{}",String::from_utf8_lossy(&output.stderr));assert!(output.stdout.is_empty());assert!(String::from_utf8_lossy(&output.stderr).contains("no generator named"));}else{assert_eq!(output.status.code(),Some(1),"{}",String::from_utf8_lossy(&output.stderr));let mut lines=output.stdout.split(|byte|*byte==b'\n');let header:serde_json::Value=serde_json::from_slice(lines.next().unwrap()).unwrap();let report:serde_json::Value=serde_json::from_slice(lines.next().unwrap()).unwrap();assert!(lines.all(|line|line.is_empty()));assert_eq!(header["status"],"completed");assert_eq!(header["clean"],false);assert_eq!(report["clean"],false);assert_eq!(report["committed"],false);assert_eq!(report["diagnostics"].as_array().unwrap().len(),1);assert!(report["diagnostics"][0]["message"].as_str().unwrap().contains("nothing to type"));assert_eq!(report["rows"].as_array().unwrap().len(),if case==0{0}else{2});assert!(report["changed"].as_array().unwrap().is_empty());assert!(report["cleanup"].as_array().unwrap().is_empty());if case==1{assert!(report["rows"][0]["path"].as_str().unwrap().ends_with("Alpha.d.ts"));assert!(report["rows"][1]["path"].as_str().unwrap().ends_with("Zed.d.ts"));}
   let args=[OsStr::new("generate-ordinary"),OsStr::new("--workspace"),root.as_os_str(),OsStr::new("--cache-root"),cache.as_os_str(),OsStr::new("--check"),OsStr::new("ui_types")];let ordinary=transport.run_program(Path::new(env!("CARGO_BIN_EXE_dmbc")),&args,Duration::from_secs(30)).unwrap();assert_eq!(ordinary.status.code(),Some(1),"{}",String::from_utf8_lossy(&ordinary.stderr));let end=ordinary.stdout.iter().position(|byte|*byte==b'\n').unwrap();let header:serde_json::Value=serde_json::from_slice(&ordinary.stdout[..end]).unwrap();let text=std::str::from_utf8(&ordinary.stdout[end+1..]).unwrap();assert_eq!(header["length"].as_u64(),Some(text.len()as u64));assert_eq!(header["hash"],serde_json::to_value(dq_analyze::selected_exclusions_wire::Hex128(xxhash_rust::xxh3::xxh3_128(text.as_bytes()))).unwrap());assert_eq!(text.matches("nothing to type").count(),1);let diagnostic=text.find("nothing to type").unwrap();if case==0{let display=text.find(&format!("fresh {}",root.join("tgui/packages/tgui/interfaces/generated").display())).unwrap();assert!(diagnostic<display);}else{assert!(text.find("Alpha.d.ts").unwrap()<diagnostic);assert!(diagnostic<text.find("Zed.d.ts").unwrap());}
  }assert_eq!(fs::read_to_string(root.join("code/probe.dm")).unwrap(),source);assert!(!root.join("tgui/packages/tgui/interfaces/generated").exists());
 }
}
